1	import { spawn } from 'node:child_process';
2	import { createHash } from 'node:crypto';
3	import { createServer } from 'node:http';
4	import { mkdir, readdir, readFile, rename, rm, writeFile } from 'node:fs/promises';
5	import * as path from 'pathe';
6	import { chromium } from 'playwright';
7	import { joinURL, parseHost, parseURL } from 'ufo';
8	import { canonicalize } from '../../../core/src/receipts/canonicalize.ts';
9	import {
10		craEntryDocument,
11		craNodeGlobalsModuleId,
12	} from '../../../frameworks/react/src/react-cra-vite-adapter.ts';
13	
14	/**
15	 * Fixture-scoped orchestration for the HospitalRun create-react-app to Vite 8
16	 * lanes: it regenerates the entry document, builds the era-pinned webpack
17	 * baseline twice in its own runtime cell, builds the Vite target twice on the
18	 * maintained runtime, and proves each built lane boots in a browser. Every
19	 * capability it exercises is generic and lives in @versionless/react; only the
20	 * paths, the runtime cell and the environment are application knowledge and
21	 * they live here.
22	 */
23	
24	const repositoryRoot = path.resolve(import.meta.dirname, '../../../..');
25	const targetRoot = path.join(repositoryRoot, '.versionless/work/react-hospitalrun/target');
26	const baselineRoot = path.join(repositoryRoot, '.versionless/work/react-hospitalrun/baseline');
27	const viteConfig = path.join(repositoryRoot, 'fixtures/react-hospitalrun/vite.config.ts');
28	const viteBinary = path.join(repositoryRoot, 'node_modules/.bin/vite');
29	
30	/**
31	 * The era runtime cell: the Node 12.14.1 darwin-x64 build the ingest already
32	 * acquired and digest-verified, run under Rosetta 2. It is the runtime the
33	 * baseline's own toolchain needs, and it is never used for the target lane.
34	 */
35	const eraRuntimeRoot = path.join(
36		repositoryRoot,
37		'.versionless/cache/react-mycrypto-runtime/node-v12.14.1-darwin-x64',
38	);
39	const eraNodeBinary = path.join(eraRuntimeRoot, 'bin/node');
40	const eraNpmCli = path.join(eraRuntimeRoot, 'lib/node_modules/npm/bin/npm-cli.js');
41	
42	/** The report the fixture's Vite config writes for the implicit-global capability. */
43	const implicitGlobalsReport = path.join(targetRoot, 'implicit-globals.json');
44	
45	const craEnvironment = { NODE_ENV: 'production', PUBLIC_URL: '' } as const;
46	
47	const sha256 = (value: Buffer | string): string => createHash('sha256').update(value).digest('hex');
48	
49	/**
50	 * The digest scheme every lane inventory in this fixture uses, stated so a
51	 * reader can recompute it from the recorded file list alone.
52	 */
53	export const laneDigestScheme = 'sha256(canonicalize(files))';
54	
55	/**
56	 * Regenerate the Vite entry document from the immutable create-react-app
57	 * template. The bootstrap module carries webpack's injected `process`, `Buffer`
58	 * and `setImmediate` bindings and is evaluated before the application entry.
59	 */
60	export async function writeHospitalRunEntryDocument(root = targetRoot): Promise<string> {
61		const template = await readFile(path.join(root, 'public/index.html'), 'utf8');
62		const document = craEntryDocument({
63			template,
64			entryModule: '/src/index.tsx',
65			environment: craEnvironment,
66			bootstrapModules: [craNodeGlobalsModuleId],
67		});
68		await writeFile(path.join(root, 'index.html'), document);
69		return document;
70	}
71	
72	async function run(
73		command: string,
74		args: readonly string[],
75		cwd: string,
76		environment: Readonly<Record<string, string>> = {},
77	): Promise<void> {
78		await new Promise<void>((resolve, reject) => {
79			const child = spawn(command, [...args], {
80				cwd,
81				stdio: ['ignore', 'pipe', 'pipe'],
82				env: {
83					...process.env,
84					npm_config_offline: 'true',
85					VERSIONLESS_NETWORK_MODE: 'offline',
86					...environment,
87				},
88			});
89			const errors: string[] = [];
90			child.stderr.on('data', (chunk: Buffer) => errors.push(chunk.toString('utf8')));
91			child.stdout.on('data', () => undefined);
92			child.on('error', reject);
93			child.on('close', (code) =>
94				code === 0
95					? resolve()
96					: reject(new Error(`${command} exited ${code}: ${errors.join('')}`)),
97			);
98		});
99	}
100	
101	export type LaneFile = Readonly<{ path: string; sha256: string }>;
102	export type LaneInventory = Readonly<{ digest: string; files: readonly LaneFile[] }>;
103	
104	async function filesBelow(directory: string): Promise<string[]> {
105		const found: string[] = [];
106		for (const entry of await readdir(directory, { withFileTypes: true })) {
107			const item = path.join(directory, entry.name);
108			if (entry.isDirectory()) found.push(...(await filesBelow(item)));
109			else if (entry.isFile()) found.push(item);
110		}
111		return found;
112	}
113	
114	/**
115	 * The lane inventory and its digest, under the reproducible scheme this corpus
116	 * uses elsewhere: sha256 over the canonicalized file list, so any reader can
117	 * recompute the digest from the record alone. The canonicalizer is the one the
118	 * receipt layer signs with, imported rather than re-implemented.
119	 */
120	export async function laneInventory(directory: string): Promise<LaneInventory> {
121		const files: LaneFile[] = [];
122		for (const file of await filesBelow(directory))
123			files.push({
124				path: path.relative(directory, file).split(path.sep).join('/'),
125				sha256: sha256(await readFile(file)),
126			});
127		files.sort((left, right) => (left.path === right.path ? 0 : left.path < right.path ? -1 : 1));
128		return { digest: sha256(canonicalize(files)), files };
129	}
130	
131	/** Build the target lane once into its own output directory. */
132	export async function buildTargetLane(
133		outDirectory: string,
134		root = targetRoot,
135	): Promise<LaneInventory> {
136		const absolute = path.join(root, outDirectory);
137		await rm(absolute, { recursive: true, force: true });
138		await run(viteBinary, ['build', '--config', viteConfig, '--outDir', absolute], root);
139		return laneInventory(absolute);
140	}
141	
142	/**
143	 * Build the era-pinned baseline once with its own toolchain. `react-scripts
144	 * build` always writes to `build/`, so the output is moved into the run's own
145	 * directory afterwards. `CI` is forced empty rather than inherited, because
146	 * create-react-app 3 promotes warnings to errors when it is set and the lane
147	 * must not depend on the host's shell.
148	 */
149	export async function buildBaselineLane(
150		outDirectory: string,
151		root = baselineRoot,
152	): Promise<LaneInventory> {
153		const staging = path.join(root, 'build');
154		const absolute = path.join(root, outDirectory);
155		await rm(staging, { recursive: true, force: true });
156		await rm(absolute, { recursive: true, force: true });
157		await run(eraNodeBinary, [eraNpmCli, 'run', 'build'], root, {
158			CI: '',
159			PATH: `${path.join(eraRuntimeRoot, 'bin')}:${process.env.PATH ?? ''}`,
160		});
161		await rename(staging, absolute);
162		return laneInventory(absolute);
163	}
164	
165	export type CraImplicitGlobalReportEntry = Readonly<{
166		module: string;
167		names: readonly string[];
168	}>;
169	
170	/**
171	 * The dependency modules that needed webpack 4's sloppy-mode CommonJS wrapper,
172	 * as the Vite build observed them. Paths are relative to the work area, so the
173	 * record carries no host-specific absolute path.
174	 */
175	export async function readImplicitGlobalReport(): Promise<readonly CraImplicitGlobalReportEntry[]> {
176		return JSON.parse(
177			await readFile(implicitGlobalsReport, 'utf8'),
178		) as CraImplicitGlobalReportEntry[];
179	}
180	
181	const mimeTypes: Readonly<Record<string, string>> = Object.freeze({
182		'.css': 'text/css',
183		'.html': 'text/html',
184		'.ico': 'image/x-icon',
185		'.js': 'text/javascript',
186		'.json': 'application/json',
187		'.map': 'application/json',
188		'.png': 'image/png',
189		'.txt': 'text/plain',
190	});
191	
192	export type BootObservation = Readonly<{
193		result: 'boot' | 'no-boot';
194		rootElementBytes: number;
195		consoleErrors: readonly string[];
196		pageErrors: readonly string[];
197		failedRequests: readonly string[];
198		successfulNonLoopback: readonly string[];
199		documentTitle: string;
200		headingText: string;
201	}>;
202	
203	/**
204	 * Serve a built lane from loopback and observe whether it boots: `#root` must
205	 * render non-empty and the page must raise no console or page error. Every
206	 * non-loopback request is refused, so nothing observed here can depend on a
207	 * network the evidence does not record.
208	 */
209	export async function observeBoot(directory: string): Promise<BootObservation> {
210		const server = createServer((request, response) => {
211			void (async () => {
212				const pathname = parseURL(request.url ?? '/').pathname || '/';
213				let file = path.join(directory, pathname);
214				let body: Buffer;
215				try {
216					body = await readFile(file);
217				} catch {
218					file = path.join(directory, 'index.html');
219					body = await readFile(file);
220				}
221				response.writeHead(200, {
222					'content-type': mimeTypes[path.extname(file)] ?? 'application/octet-stream',
223				});
224				response.end(body);
225			})();
226		});
227		await new Promise<void>((resolve) => server.listen(0, '127.0.0.1', resolve));
228		const address = server.address();
229		const port = typeof address === 'object' && address !== null ? address.port : 0;
230		const origin = `http://127.0.0.1:${port}`;
231		const browser = await chromium.launch();
232		const consoleErrors: string[] = [];
233		const pageErrors: string[] = [];
234		const failedRequests: string[] = [];
235		const successfulNonLoopback: string[] = [];
236		const loopback = ['127.0.0.1', 'localhost', '::1'];
237		try {
238			const context = await browser.newContext();
239			await context.route('**/*', async (route) => {
240				const host = parseHost(parseURL(route.request().url()).host ?? '').hostname;
241				if (loopback.includes(host)) await route.continue();
242				else await route.fulfill({ status: 204, body: '' });
243			});
244			const page = await context.newPage();
245			page.on('console', (message) => {
246				if (message.type() === 'error') consoleErrors.push(message.text());
247			});
248			page.on('pageerror', (error) => pageErrors.push(error.message));
249			page.on('requestfailed', (request) =>
250				failedRequests.push(`${request.url()} :: ${request.failure()?.errorText ?? 'unknown'}`),
251			);
252			page.on('response', (response) => {
253				const host = parseHost(parseURL(response.url()).host ?? '').hostname;
254				if (!loopback.includes(host) && response.ok())
255					successfulNonLoopback.push(response.url());
256			});
257			await page.goto(joinURL(origin, '/'), { waitUntil: 'networkidle' });
258			await page.locator('#root *').first().waitFor({ timeout: 30_000 });
259			const rootElementBytes = await page.evaluate(
260				() => document.querySelector('#root')?.innerHTML.length ?? 0,
261			);
262			const documentTitle = await page.title();
263			const headingText = (await page.locator('h1, h2, h3').first().textContent()) ?? '';
264			await context.close();
265			return {
266				result: rootElementBytes > 0 ? 'boot' : 'no-boot',
267				rootElementBytes,
268				consoleErrors,
269				pageErrors,
270				failedRequests,
271				successfulNonLoopback,
272				documentTitle,
273				headingText: headingText.trim(),
274			};
275		} finally {
276			await browser.close();
277			await new Promise<void>((resolve) => server.close(() => resolve()));
278		}
279	}
280	
281	/**
282	 * The console errors a booting lane of this application is allowed to raise,
283	 * keyed by the kind of break they are. The webpack baseline registers the
284	 * create-react-app service worker from `src/index.tsx`; that worker's own
285	 * script fails to evaluate under the offline loopback host, and the failure is
286	 * reported here rather than resolved. The Vite target emits no service worker
287	 * at all, so it raises none of these.
288	 */
289	export const knownConsoleErrorInventory: Readonly<Record<string, string>> = Object.freeze({
290		'service-worker-registration': 'Error during service worker registration:',
291	});
292	
293	export type ConsoleErrorClassification = Readonly<{
294		known: Readonly<Record<string, number>>;
295		unexpected: readonly string[];
296	}>;
297	
298	/**
299	 * Sort observed console errors into the known inventory and everything else.
300	 * Only the kind and the count are kept for the known ones: their text carries
301	 * the loopback server's ephemeral port, which would make the evidence differ
302	 * between otherwise identical runs.
303	 */
304	export function classifyConsoleErrors(errors: readonly string[]): ConsoleErrorClassification {
305		const known: Record<string, number> = {};
306		const unexpected: string[] = [];
307		for (const error of errors) {
308			const kind = Object.keys(knownConsoleErrorInventory)
309				.sort()
310				.find((candidate) => error.includes(knownConsoleErrorInventory[candidate] as string));
311			if (kind === undefined) unexpected.push(error);
312			else known[kind] = (known[kind] ?? 0) + 1;
313		}
314		return { known, unexpected };
315	}
316	
317	/**
318	 * A boot is only proven when the application actually rendered and the page
319	 * raised nothing beyond the known inventory: no page error, no unexpected
320	 * console error, no failed request, and no successful request off loopback.
321	 */
322	export function bootIsClean(observation: BootObservation): boolean {
323		return (
324			observation.result === 'boot' &&
325			observation.pageErrors.length === 0 &&
326			classifyConsoleErrors(observation.consoleErrors).unexpected.length === 0 &&
327			observation.failedRequests.length === 0 &&
328			observation.successfulNonLoopback.length === 0
329		);
330	}
331	
332	export type LaneRun = Readonly<{
333		first: LaneInventory;
334		second: LaneInventory;
335		equal: boolean;
336		boot: BootObservation;
337		consoleErrors: ConsoleErrorClassification;
338		booted: boolean;
339	}>;
340	
341	export type TargetLaneRun = LaneRun &
342		Readonly<{
343			entryDocumentSha256: string;
344			implicitGlobals: readonly CraImplicitGlobalReportEntry[];
345		}>;
346	
347	/** Regenerate the entry document, build the target lane twice, then boot it. */
348	export async function runHospitalRunTargetLane(root = targetRoot): Promise<TargetLaneRun> {
349		const document = await writeHospitalRunEntryDocument(root);
350		const first = await buildTargetLane('build-vite-run1', root);
351		const second = await buildTargetLane('build-vite-run2', root);
352		const boot = await observeBoot(path.join(root, 'build-vite-run1'));
353		return {
354			entryDocumentSha256: sha256(document),
355			implicitGlobals: await readImplicitGlobalReport(),
356			first,
357			second,
358			equal: first.digest === second.digest,
359			boot,
360			consoleErrors: classifyConsoleErrors(boot.consoleErrors),
361			booted: bootIsClean(boot),
362		};
363	}
364	
365	/** Build the era-pinned baseline lane twice in its own runtime cell, then boot it. */
366	export async function runHospitalRunBaselineLane(root = baselineRoot): Promise<LaneRun> {
367		const first = await buildBaselineLane('build-run1', root);
368		const second = await buildBaselineLane('build-run2', root);
369		const boot = await observeBoot(path.join(root, 'build-run1'));
370		return {
371			first,
372			second,
373			equal: first.digest === second.digest,
374			boot,
375			consoleErrors: classifyConsoleErrors(boot.consoleErrors),
376			booted: bootIsClean(boot),
377		};
378	}
379	
380	export type HospitalRunLanes = Readonly<{ baseline: LaneRun; target: TargetLaneRun }>;
381	
382	/** Both lanes, each built twice and each booted. */
383	export async function runHospitalRunLanes(): Promise<HospitalRunLanes> {
384		return {
385			baseline: await runHospitalRunBaselineLane(),
386			target: await runHospitalRunTargetLane(),
387		};
388	}
389	
390	/** Inventory an already-built lane, for a lane built outside this orchestration. */
391	export async function readBuiltLane(directory: string): Promise<LaneInventory> {
392		return laneInventory(directory);
393	}
394	
395	/** Write an observation document into the run evidence directory. */
396	export async function writeRunObservation(name: string, value: unknown): Promise<string> {
397		const directory = path.join(repositoryRoot, 'evidence/runs/react-hospitalrun');
398		await mkdir(directory, { recursive: true });
399		const file = path.join(directory, name);
400		await writeFile(file, `${JSON.stringify(value, null, '\t')}\n`);
401		return file;
402	}
