				? {}
				: { applicationRoot: options.applicationRoot },
		),
		createCraGlobalIdentifierPlugin(),
		createCraPublicDirectoryPlugin({
			directory: options.publicDirectory,
			exclude: [options.templateFile ?? 'index.html'],
		}),
	];
}

